const out = $input.first().json;
let raw = (out.message && out.message.content) ? String(out.message.content) : '';
raw = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');

let g = null;
try {
  g = JSON.parse(raw);
} catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) {
    try { g = JSON.parse(m[0]); } catch (e2) { g = null; }
  }
}

const parsed = g !== null && typeof g === 'object' && !Array.isArray(g);
const valid = ['low', 'medium', 'high'];
const threat_level = parsed && valid.includes(g.threat_level) ? g.threat_level : 'high';

// Politica fail-closed: si el modelo no devuelve JSON valido, se bloquea.
// Un nivel "high" siempre se bloquea, aunque el modelo diga lo contrario.
const should_block = !parsed || g.should_block === true || threat_level === 'high';

const n = $('Normalizar').first().json;
return [{ json: {
  ...n,
  threat_level,
  risk_category: (parsed && typeof g.risk_category === 'string' && g.risk_category.trim()) ? g.risk_category.trim() : (parsed ? 'none' : 'parse_error'),
  explanation: (parsed && typeof g.explanation === 'string') ? g.explanation : 'El Guardian no devolvio JSON valido; se aplica politica fail-closed.',
  should_block,
  parse_error: !parsed,
  guardian_model: out.model || 'qwen2.5:7b'
} }];

