const g = $('Parse Guardian').first().json;
const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.content);

const norm = rows.map(r => ({
  content: String(r.content || '').slice(0, 1000),
  source: r.source || (r.metadata && r.metadata.source) || 'desconocido',
  score: Number(r.score ?? r.similarity ?? 0)
}));

const context = norm
  .map((r, i) => '[Fragmento ' + (i + 1) + '] (' + r.source + ', score ' + r.score.toFixed(4) + ')\n' + r.content)
  .join('\n\n')
  .slice(0, 6000);

const owasp = [
  'LLM01:2025 - Prompt Injection',
  'LLM02:2025 - Sensitive Information Disclosure',
  'LLM03:2025 - Supply Chain',
  'LLM04:2025 - Data and Model Poisoning',
  'LLM05:2025 - Improper Output Handling',
  'LLM06:2025 - Excessive Agency',
  'LLM07:2025 - System Prompt Leakage',
  'LLM08:2025 - Vector and Embedding Weaknesses',
  'LLM09:2025 - Misinformation',
  'LLM10:2025 - Unbounded Consumption'
].join('\n');

const is_attack = g.threat_level === 'medium' || g.threat_level === 'high' || g.should_block === true;

const general_system = 'Eres Analyst, experto en seguridad de LLMs. Responde en espanol usando UNICAMENTE el contexto recuperado. Si el contexto no alcanza, dilo. La consulta es conceptual o educativa: responde directamente la pregunta, explica el tema con claridad y cita las fuentes del corpus al final. No clasifiques la consulta como ataque ni fuerces el catalogo OWASP. Se conciso: maximo 180 palabras en total.';

const attack_system = 'Eres Analyst, experto en seguridad de LLMs (red teaming). Responde en espanol usando UNICAMENTE el contexto recuperado. Si el contexto no alcanza, dilo. Analiza la consulta como un ataque o vulnerabilidad. Se conciso: maximo 300 palabras en total. Usa este catalogo OWASP unico y copia la categoria EXACTAMENTE como aparece (incluido el ano 2025):\n' + owasp + '\n\nEstructura tu respuesta asi:\n1. Tipo de ataque\n2. Categoria OWASP (texto exacto del catalogo)\n3. Mecanismo\n4. Riesgo\n5. Defensa recomendada\n6. Fuentes citadas del corpus';

const analyst_system = is_attack ? attack_system : general_system;

const analyst_user = 'Resultado del Guardian: nivel=' + g.threat_level + ', categoria=' + g.risk_category + '.\n\nContexto recuperado:\n' + (context || '(sin resultados)') + '\n\nConsulta: ' + g.prompt;

return [{ json: {
  ...g,
  context,
  analyst_system,
  analyst_user,
  is_attack,
  analyst_model: 'qwen2.5:3b',
  num_chunks: norm.length,
  sources: norm.map(r => ({ source: r.source, score: r.score }))
} }];

